async function haikuTonePolish(env, draft) {
  try {
    const res = await fetch(ANTHROPIC_URL4, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": env.ANTHROPIC_API_KEY,
        "anthropic-version": ANTHROPIC_VERSION4
      },
      body: JSON.stringify({
        model: "claude-haiku-4-5",
        max_tokens: 1500,
        temperature: 0.2,
        system: 'You rewrite the tone of the supplied email draft to sound natural and professional. RULES: never change or remove numbers, dates, client names, insurer names, referral flags, or listed items. Do not add facts. Return ONLY JSON: {"subject":"...","body":"..."}.',
        messages: [
          { role: "user", content: "SUBJECT: " + draft.subject + "\n\nBODY:\n" + draft.body }
        ]
      })
    });
    if (!res.ok) return null;
    const data = await res.json();
    const text = data.content?.filter((b2) => b2.type === "text").map((b2) => b2.text).join("") ?? "";
    const parsed = JSON.parse(text.replace(/```json|```/g, "").trim());
    if (typeof parsed?.subject !== "string" || typeof parsed?.body !== "string") return null;
    return { subject: parsed.subject, body: parsed.body };
  } catch {
    return null;
  }
}
