async function legacySonnetEmail(env, emailType, inputLines) {
  try {
    const res = await fetch(ANTHROPIC_URL4, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": env.ANTHROPIC_API_KEY,
        "anthropic-version": ANTHROPIC_VERSION4
      },
      body: JSON.stringify({
        model: EMAIL_MODEL,
        max_tokens: 2e3,
        system: SYSTEM_PROMPTS[emailType],
        messages: [{ role: "user", content: inputLines.join("\n") }]
      })
    });
    if (!res.ok) {
      let detail = "";
      try {
        detail = (await res.text()).slice(0, 200).replace(/\s+/g, " ");
      } catch {
      }
      console.error("email_anthropic_error", res.status, detail);
      return { error: "email_generation_failed", status: res.status, detail, httpStatus: 502 };
    }
    const data = await res.json();
    const text = data.content?.filter((b2) => b2.type === "text").map((b2) => b2.text).join("") ?? "";
    const parsed = JSON.parse(text.replace(/```json|```/g, "").trim());
    if (typeof parsed?.subject !== "string" || typeof parsed?.body !== "string") {
      return { error: "email_invalid_shape", status: 200, httpStatus: 502 };
    }
    return { subject: parsed.subject, body: parsed.body };
  } catch {
    return { error: "email_parse_failed", status: 200, httpStatus: 502 };
  }
}
